use callisto_model::{CommandRunner, SnapshotReport, SCHEMA_VERSION};

use crate::error::GraphError;
use crate::plan::VersionPlan;
use crate::resolver::DependencyResolver;
use crate::Workspace;

pub fn plan_snapshot<R: CommandRunner, D: DependencyResolver>(
    ws: &Workspace<'_, R, D>,
    tag: &str,
) -> Result<(VersionPlan, SnapshotReport), GraphError> {
    // Resolve HEAD for real rather than faking it, so unrelated snapshot runs never collide.
    let sha = ws.git_access().head_sha()?;
    let sha_short = sha.short();

    // Label for the report only; each package's actual version is built in its own grammar below.
    let snapshot_tag = format!("0.0.0-{tag}-{sha_short}");
    let base_versions = ws.base_versions()?;
    // No severity cascade to seed here; `ws.tags()` only checks the propagate-failure invariant below.
    ws.tags()?;

    let mut bumps = Vec::new();
    let mut plan_bumps = Vec::new();

    let mut snapshot_versions = std::collections::BTreeMap::new();

    for pkg in ws.graph.packages() {
        let from = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
            GraphError::Manifest(callisto_model::ManifestError::MissingField {
                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
                field: "version",
            })
        })?;
        let grammar = pkg.version_grammar()?;
        let snapshot_ver = snapshot_version_for(grammar, tag, sha_short)?;
        snapshot_versions.insert(pkg.id.clone(), snapshot_ver.clone());

        let mut writes = Vec::new();
        for decl in &pkg.manifests {
            if decl.role == callisto_model::ManifestRole::Canonical {
                writes.push(crate::plan::VersionWriteTarget::Manifest(decl.path.clone()));
            }
        }

        plan_bumps.push(crate::plan::PlannedBump {
            package: pkg.id.clone(),
            from: from.clone(),
            to: snapshot_ver.clone(),
            severity: callisto_model::Severity::Patch,
            governed_by: None,
            reason: None,
            writes,
        });

        bumps.push(callisto_model::BumpRecord {
            package: pkg.id.clone(),
            from,
            to: snapshot_ver.clone(),
            severity: callisto_model::Severity::Patch,
            governed_by: None,
            reason: None,
        });
    }

    // No severity to propagate; just rewrite each dependent spec that doesn't cover `snapshot_ver`.
    let mut rewrites: std::collections::BTreeMap<crate::cascade::RewriteKey, crate::cascade::SpecRewrite> =
        std::collections::BTreeMap::new();
    let mut diagnostics = Vec::new();

    for pkg in ws.graph.packages() {
        for edge in ws.graph.dependencies_of(&pkg.id) {
            if matches!(
                edge.spec,
                callisto_model::DepSpec::Workspace(_) | callisto_model::DepSpec::Catalog(_)
            ) {
                if matches!(edge.spec, callisto_model::DepSpec::Catalog(_)) {
                    diagnostics.push(callisto_model::Diagnostic {
                        code: callisto_model::DiagnosticCode::CatalogSpecNotRewritten,
                        severity: callisto_model::DiagnosticSeverity::Warning,
                        message: format!(
                            "spec `{}` for `{}` could not be tested for coverage",
                            edge.spec.render(),
                            edge.to.display_name()
                        ),
                        package: Some(edge.from.clone()),
                        path: Some(edge.from_manifest.clone()),
                        governed_by: Some(callisto_model::ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
                        escalated_by: None,
                    });
                }
                continue;
            }
            if matches!(edge.spec, callisto_model::DepSpec::Opaque(_)) {
                continue;
            }
            let Some(snap_to) = snapshot_versions.get(&edge.to) else {
                continue;
            };
            // snap_to is always SemVer-parsed, so a Pep440 edge here surfaces as a GrammarMismatch, not silently.
            let covers =
                crate::cascade::coverage(&edge.spec, snap_to).map_err(|source| GraphError::GrammarMismatch {
                    from: edge.from.clone(),
                    to: edge.to.clone(),
                    source,
                })?;
            if matches!(covers, callisto_model::Coverage::Covers) {
                continue;
            }

            let eco = crate::cascade::manifest_ecosystem(edge.from.ecosystem(), &edge.from_manifest);

            match crate::cascade::rewrite_spec(&edge.spec, snap_to, eco, &ws.config.cascade) {
                crate::cascade::RewriteOutcome::Rewritten(to_spec) => {
                    let key = crate::cascade::RewriteKey {
                        target: if edge.inherited {
                            crate::cascade::DepWriteTarget::CargoWorkspaceDependency {
                                root_manifest: edge.from_manifest.clone(),
                            }
                        } else {
                            crate::cascade::DepWriteTarget::Manifest(edge.from_manifest.clone())
                        },
                        name: ws
                            .identity
                            .native_name(&edge.to, eco)
                            .map(str::to_string)
                            .unwrap_or_else(|| edge.to.name().to_string()),
                        kind: if edge.inherited { None } else { Some(edge.kind) },
                    };
                    rewrites
                        .entry(key.clone())
                        .or_insert_with(|| crate::cascade::SpecRewrite {
                            key,
                            dependency: edge.to.clone(),
                            from: edge.spec.clone(),
                            to: to_spec,
                        });
                }
                crate::cascade::RewriteOutcome::LeftAlone(dg) => {
                    diagnostics.push(dg);
                }
            }
        }
    }
    let rewrites: Vec<_> = rewrites.into_values().collect();

    let (platform_writes, optional_dep_updates) =
        crate::commands::version::platform_version_writes(ws, &snapshot_versions)?;

    let plan = VersionPlan {
        bumps: plan_bumps,
        rewrites,
        platform_writes,
        optional_dep_updates,
        changelog_writes: Vec::new(),
        consumed_changesets: Vec::new(),
        pre_state_update: None,
        pre_json_path: std::path::PathBuf::new(),
        pre_json_original_text: None,
        delete_pre_json: None,
        pre_cursor_updates: Vec::new(),
        observed_versions: std::collections::BTreeMap::new(),
        diagnostics,
    };

    let report = SnapshotReport {
        schema_version: SCHEMA_VERSION,
        snapshot_tag,
        bumps,
        diagnostics: Vec::new(),
    };

    Ok((plan, report))
}

/// Builds a package's snapshot version in its own grammar: `0.0.0-<tag>-<sha>` for SemVer,
/// the equivalent PEP 440 dev/local form `0.0.0.dev0+<tag>.<sha>` for Pep440.
fn snapshot_version_for(
    grammar: callisto_model::VersionGrammar,
    tag: &str,
    sha_short: &str,
) -> Result<callisto_model::Version, GraphError> {
    let raw = match grammar {
        callisto_model::VersionGrammar::SemVer => format!("0.0.0-{tag}-{sha_short}"),
        callisto_model::VersionGrammar::Pep440 => format!("0.0.0.dev0+{tag}.{sha_short}"),
        _ => {
            return Err(GraphError::Bump(
                callisto_model::format::BumpError::UnsupportedGrammar { grammar },
            ));
        }
    };
    callisto_model::Version::parse(&raw, grammar).map_err(|err| {
        GraphError::Bump(callisto_model::format::BumpError::ComputedVersionInvalid {
            raw,
            message: err.message,
        })
    })
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use crate::locate::IgnoreWalkLocator;
    use crate::Workspace;
    use callisto_model::{CommandError, CommandOutput, CommandRunner};

    use super::plan_snapshot;

    struct FailingTagsRunner;

    impl CommandRunner for FailingTagsRunner {
        fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            if program == "git" && args == ["tag", "--list"] {
                return Err(CommandError::NotFound {
                    program: "git".to_string(),
                });
            }
            Ok(CommandOutput {
                exit_code: Some(0),
                stdout: String::new(),
                stderr: String::new(),
            })
        }
    }

    fn git_init_with_commit(root: &Path) {
        callisto_fixtures::git::init_repo(root);
        std::fs::write(root.join(".gitkeep"), "").unwrap();
        for args in [vec!["add", "."], vec!["commit", "-q", "-m", "init"]] {
            std::process::Command::new("git")
                .args(&args)
                .current_dir(root)
                .output()
                .expect("git must be installed");
        }
    }

    /// When ws.tags() (TagIndex::build) fails, plan_snapshot must
    /// propagate that Err rather than silently proceeding with an
    /// empty/partial TagIndex.
    #[test]
    fn plan_snapshot_propagates_tags_build_failure() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        std::fs::create_dir_all(root.join("pkg-alpha")).unwrap();
        std::fs::write(
            root.join("pkg-alpha/Cargo.toml"),
            "[package]\nname = \"pkg-alpha\"\nversion = \"1.0.0\"\n",
        )
        .unwrap();

        let locator = IgnoreWalkLocator::new(root);
        let runner = FailingTagsRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner)
            .expect("workspace must load even though git tags will later fail");

        let result = plan_snapshot(&ws, "canary");

        assert!(
            result.is_err(),
            "plan_snapshot must propagate a tags-build failure as Err, not silently proceed"
        );
    }

    /// Plan_snapshot's synthetic snapshot version overwrites every
    /// PlannedBump.to and BumpRecord.to unconditionally, even for members of
    /// a Fixed group -- the cascade-stage target the new Fixed-group
    /// convergence block computes internally is discarded.
    #[test]
    fn plan_snapshot_overwrites_fixed_group_targets_with_synthetic_version() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        git_init_with_commit(root);

        std::fs::create_dir_all(root.join("pkg-a")).unwrap();
        std::fs::write(
            root.join("pkg-a/Cargo.toml"),
            "[package]\nname = \"pkg-a\"\nversion = \"2.0.0\"\n",
        )
        .unwrap();
        std::fs::create_dir_all(root.join("pkg-b")).unwrap();
        std::fs::write(
            root.join("pkg-b/Cargo.toml"),
            "[package]\nname = \"pkg-b\"\nversion = \"0.1.0\"\n",
        )
        .unwrap();
        std::fs::write(
            root.join("callisto.toml"),
            "[[fixed-group]]\nname = \"ab\"\nmembers = [\"pkg-a\", \"pkg-b\"]\n",
        )
        .unwrap();

        let locator = IgnoreWalkLocator::new(root);
        let runner = callisto_fixtures::git::GitRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let (plan, report) = plan_snapshot(&ws, "canary").expect("plan_snapshot must succeed");

        let expected_prefix = "0.0.0-canary-";
        for bump in &plan.bumps {
            assert!(
                bump.to.render().starts_with(expected_prefix),
                "PlannedBump.to for {:?} must be the synthetic snapshot version, got {}",
                bump.package,
                bump.to.render()
            );
        }
        for bump in &report.bumps {
            assert!(
                bump.to.render().starts_with(expected_prefix),
                "BumpRecord.to for {:?} must be the synthetic snapshot version, got {}",
                bump.package,
                bump.to.render()
            );
        }
    }

    /// `core = "1.0.0"` covers the patch-bumped 1.0.1 but not the snapshot pre-release.
    #[test]
    fn plan_snapshot_rewrites_spec_that_only_the_snapshot_version_leaves_out_of_range() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        git_init_with_commit(root);

        std::fs::create_dir_all(root.join("crates/core/src")).unwrap();
        std::fs::write(
            root.join("crates/core/Cargo.toml"),
            "[package]\nname = \"core\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
        )
        .unwrap();
        std::fs::write(root.join("crates/core/src/lib.rs"), "").unwrap();

        std::fs::create_dir_all(root.join("crates/app/src")).unwrap();
        std::fs::write(
            root.join("crates/app/Cargo.toml"),
            "[package]\nname = \"app\"\nversion = \"1.0.0\"\nedition = \"2021\"\n\n[dependencies]\ncore = { path = \"../core\", version = \"1.0.0\" }\n",
        )
        .unwrap();
        std::fs::write(root.join("crates/app/src/lib.rs"), "").unwrap();

        std::fs::write(
            root.join("Cargo.toml"),
            "[workspace]\nmembers = [\"crates/core\", \"crates/app\"]\nresolver = \"2\"\n",
        )
        .unwrap();

        let locator = IgnoreWalkLocator::new(root);
        let runner = callisto_fixtures::git::GitRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let (plan, _report) = plan_snapshot(&ws, "canary").expect("plan_snapshot must succeed");

        let app_core_rewrite = plan
            .rewrites
            .iter()
            .find(|r| r.dependency.name() == "core")
            .expect("the out-of-range `core = \"1.0.0\"` spec on app must be rewritten");

        assert_ne!(
            app_core_rewrite.from, app_core_rewrite.to,
            "the spec must actually change, not be left at the stale `1.0.0` bare requirement"
        );
    }

    /// `0.0.0-canary-<sha>` is not valid PEP 440, so a Pypi package needs its own snapshot form.
    #[test]
    fn plan_snapshot_builds_pep440_version_for_a_pypi_package() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        git_init_with_commit(root);

        std::fs::write(
            root.join("pyproject.toml"),
            "[tool.uv.workspace]\nmembers = [\"py/core\", \"py/app\"]\n",
        )
        .unwrap();
        std::fs::create_dir_all(root.join("py/core")).unwrap();
        std::fs::write(
            root.join("py/core/pyproject.toml"),
            "[project]\nname = \"core-py\"\nversion = \"1.0.0\"\nrequires-python = \">=3.9\"\ndependencies = []\n",
        )
        .unwrap();
        std::fs::create_dir_all(root.join("py/app")).unwrap();
        std::fs::write(
            root.join("py/app/pyproject.toml"),
            "[project]\nname = \"app-py\"\nversion = \"1.0.0\"\nrequires-python = \">=3.9\"\n\
             dependencies = [\"core-py>=1.0.0,<2.0.0\"]\n\n\
             [tool.uv.sources]\ncore-py = { workspace = true }\n",
        )
        .unwrap();

        let locator = IgnoreWalkLocator::new(root);
        let runner = callisto_fixtures::git::GitRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let (plan, report) = plan_snapshot(&ws, "canary").expect("plan_snapshot must succeed for a Pypi package");

        for bump in &report.bumps {
            assert!(
                bump.to.grammar() == callisto_model::VersionGrammar::Pep440,
                "package {:?}'s snapshot version must parse as PEP 440, got {}",
                bump.package,
                bump.to.render()
            );
            assert!(
                bump.to.render().starts_with("0.0.0.dev0+canary."),
                "expected the PEP 440 dev/local snapshot form, got {}",
                bump.to.render()
            );
        }

        let dep_rewrite = plan
            .rewrites
            .iter()
            .find(|r| r.dependency.name() == "core-py")
            .expect("the out-of-range `core-py>=1.0.0,<2.0.0` spec on app-py must be rewritten");
        assert_ne!(
            dep_rewrite.from, dep_rewrite.to,
            "the PEP 440 spec must actually change to cover the snapshot's dev/local version"
        );
    }

    /// Same scenario as above, but applied to disk: `cargo metadata` must resolve once the rewritten spec lands.
    #[test]
    fn plan_snapshot_apply_then_cargo_metadata_succeeds() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        git_init_with_commit(root);

        std::fs::create_dir_all(root.join("crates/core/src")).unwrap();
        std::fs::write(
            root.join("crates/core/Cargo.toml"),
            "[package]\nname = \"core\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
        )
        .unwrap();
        std::fs::write(root.join("crates/core/src/lib.rs"), "").unwrap();

        std::fs::create_dir_all(root.join("crates/app/src")).unwrap();
        std::fs::write(
            root.join("crates/app/Cargo.toml"),
            "[package]\nname = \"app\"\nversion = \"1.0.0\"\nedition = \"2021\"\n\n\
             [dependencies]\ncore = { path = \"../core\", version = \"1.0.0\" }\n",
        )
        .unwrap();
        std::fs::write(root.join("crates/app/src/lib.rs"), "").unwrap();

        std::fs::write(
            root.join("Cargo.toml"),
            "[workspace]\nmembers = [\"crates/core\", \"crates/app\"]\nresolver = \"2\"\n",
        )
        .unwrap();

        let locator = IgnoreWalkLocator::new(root);
        let runner = callisto_fixtures::git::GitRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let (plan, _report) = plan_snapshot(&ws, "canary").expect("plan_snapshot must succeed");

        let permit = callisto_model::ApplyPermit::force_for_tests();
        let opts = crate::apply::ApplyOptions::default();
        crate::apply::apply_version_plan(root, &plan, &runner, &opts, &permit).expect("apply must succeed");

        let target_dir = tmp.path().join("target");
        let output = std::process::Command::new("cargo")
            .args(["metadata", "--no-deps", "--format-version", "1"])
            .env("CARGO_TARGET_DIR", &target_dir)
            .current_dir(root)
            .output()
            .expect("cargo must be installed");

        assert!(
            output.status.success(),
            "cargo metadata must succeed after snapshot rewrites `core`'s spec; stderr: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    /// Plan_snapshot must never call
    /// pre_mutation_checks -- snapshot mode assigns every package the
    /// identical synthetic version, so there is no distinct-target
    /// divergence for pre_mutation_checks to ever catch here.
    #[test]
    fn plan_snapshot_source_never_calls_pre_mutation_checks() {
        let source = include_str!("snapshot.rs");
        // Only the production code above the `#[cfg(test)]` boundary is
        // checked -- this test module's own name and doc comments
        // necessarily mention `pre_mutation_checks` and must not cause a
        // self-match false failure.
        let production_source = source
            .split_once("#[cfg(test)]")
            .map(|(before, _)| before)
            .unwrap_or(source);
        assert!(
            !production_source.contains("pre_mutation_checks"),
            "plan_snapshot must not call pre_mutation_checks (see spec non_goals)"
        );
    }
}
use std::collections::BTreeMap;
use std::path::PathBuf;

use callisto_graph::resolver::DependencyResolver;
use callisto_graph::GraphError;
use callisto_model::{
    DepEdge, DepKind, DepSpec, ManifestDecl, ManifestFormat, ManifestRole, Package, PackageId, PublishTarget,
    ReleaseTrigger, TagTemplate,
};

#[derive(Default)]
pub struct GraphBuilder {
    packages: BTreeMap<PackageId, PackageBuilder>,
    edges: Vec<DepEdge>,
}

impl GraphBuilder {
    pub fn new() -> Self {
        Self::default()
    }

    #[allow(dead_code)]
    pub fn package(mut self, id: impl Into<PackageId>, f: impl FnOnce(PackageBuilder) -> PackageBuilder) -> Self {
        let pkg_id = id.into();
        let builder = PackageBuilder::new(pkg_id.clone());
        self.packages.insert(pkg_id, f(builder));
        self
    }

    #[allow(dead_code)]
    pub fn edge(mut self, from: impl Into<PackageId>, to: impl Into<PackageId>, kind: DepKind, spec: DepSpec) -> Self {
        let from_id = from.into();
        let to_id = to.into();
        let from_manifest = PathBuf::from(format!("{}/Cargo.toml", from_id.name()));
        self.edges.push(DepEdge {
            from: from_id,
            to: to_id,
            kind,
            spec,
            from_manifest,
            inherited: false,
        });
        self
    }

    #[allow(clippy::result_large_err)]
    pub fn build(self) -> Result<InMemoryGraph, GraphError> {
        let mut built_packages = BTreeMap::new();
        for (id, builder) in self.packages {
            built_packages.insert(id, builder.build());
        }

        let mut out_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();
        let mut in_index: BTreeMap<PackageId, Vec<usize>> = BTreeMap::new();

        for (idx, edge) in self.edges.iter().enumerate() {
            out_index.entry(edge.from.clone()).or_default().push(idx);
            in_index.entry(edge.to.clone()).or_default().push(idx);
        }

        Ok(InMemoryGraph {
            packages: built_packages,
            edges: self.edges,
            out_index,
            in_index,
        })
    }
}

pub struct PackageBuilder {
    id: PackageId,
    release_trigger: ReleaseTrigger,
    publish_to: Vec<PublishTarget>,
    changelog: Option<PathBuf>,
    tag_template: Option<TagTemplate>,
    manifests: Vec<ManifestDecl>,
}

#[allow(dead_code)]
impl PackageBuilder {
    pub fn new(id: PackageId) -> Self {
        let manifest_path = PathBuf::from(format!("{}/Cargo.toml", id.name()));
        let decl = ManifestDecl::new(manifest_path, ManifestRole::Canonical, ManifestFormat::CargoToml).unwrap();
        PackageBuilder {
            id,
            release_trigger: ReleaseTrigger::Changeset,
            publish_to: Vec::new(),
            changelog: None,
            tag_template: None,
            manifests: vec![decl],
        }
    }

    pub fn release_trigger(mut self, rt: ReleaseTrigger) -> Self {
        self.release_trigger = rt;
        self
    }

    pub fn publish_to(mut self, targets: Vec<PublishTarget>) -> Self {
        self.publish_to = targets;
        self
    }

    pub fn changelog(mut self, path: Option<PathBuf>) -> Self {
        self.changelog = path;
        self
    }

    pub fn tag_template(mut self, t: Option<TagTemplate>) -> Self {
        self.tag_template = t;
        self
    }

    pub fn manifests(mut self, m: Vec<ManifestDecl>) -> Self {
        self.manifests = m;
        self
    }

    pub fn build(self) -> Package {
        Package {
            id: self.id,
            manifests: self.manifests,
            changelog: self.changelog,
            release_trigger: self.release_trigger,
            publish_to: self.publish_to,
            tag_template: self.tag_template,
        }
    }
}

pub struct InMemoryGraph {
    packages: BTreeMap<PackageId, Package>,
    edges: Vec<DepEdge>,
    out_index: BTreeMap<PackageId, Vec<usize>>,
    in_index: BTreeMap<PackageId, Vec<usize>>,
}

/// An `IdentityIndex` reflecting every package's own canonical manifests, as
/// `ManifestWalkResolver::build` would populate it for a real workspace --
/// package-selector resolution (`--package`, `[[package]]`, `[[fixed-group]]`)
/// runs through `IdentityIndex`, not a `GraphBuilder`-built graph directly, so
/// a hand-built `Workspace` fixture needs one to resolve anything at all.
#[allow(dead_code)]
pub fn identity_for(graph: &InMemoryGraph) -> callisto_graph::IdentityIndex {
    let mut index = callisto_graph::IdentityIndex::default();
    for pkg in graph.packages() {
        for manifest in pkg.canonical_manifests() {
            index
                .native
                .insert((manifest.ecosystem(), pkg.id.name().to_string()), pkg.id.clone());
        }
    }
    index
}

impl DependencyResolver for InMemoryGraph {
    fn packages(&self) -> impl Iterator<Item = &Package> {
        self.packages.values()
    }

    fn dependencies_of(&self, id: &PackageId) -> impl Iterator<Item = &DepEdge> {
        let empty = Vec::new();
        let indices = self.out_index.get(id).unwrap_or(&empty);
        let mut result = Vec::new();
        for &idx in indices {
            result.push(&self.edges[idx]);
        }
        result.into_iter()
    }

    fn dependents_of(&self, id: &PackageId) -> impl Iterator<Item = &DepEdge> {
        let empty = Vec::new();
        let indices = self.in_index.get(id).unwrap_or(&empty);
        let mut result = Vec::new();
        for &idx in indices {
            result.push(&self.edges[idx]);
        }
        result.into_iter()
    }
}

