+            .unwrap();
+        assert_eq!(rewrite.to.render(), *target);
+        assert_eq!(
+            rewrite.key.target,
+            DepWriteTarget::Manifest("crates/app/package.json".into())
+        );
+    }
+
+    let permit = ApplyPermit::force_for_tests();
