+        root,
+        &plan,
+        &runner,
+        &ApplyOptions {
+            refresh_lockfiles: false,
+            transient: true,
+        },
+        &permit,
+    )
+    .unwrap();
+    assert!(outcome.staged.is_empty());
+    assert_eq!(
+        std::fs::read_to_string(root.join("Cargo.toml")).unwrap(),
+        root_source.replace("\"^1.0.0\"", &format!("\"^{target}\""))
+    );
