+        std::fs::read_to_string(root.join("crates/app/Cargo.toml")).unwrap(),
+        app_source
+            .replace("\"1.0.0\"", &format!("\"{target}\""))
+            .replace("\"^1.0.0\"", &format!("\"^{target}\""))
+            .replace("\"=1.0.0\"", &format!("\"={target}\""))
+    );
+    assert_eq!(
+        std::fs::read_to_string(root.join("crates/tools/Cargo.toml")).unwrap(),
+        tools_source
+            .replace("\"1.0.0\"", &format!("\"{target}\""))
+            .replace("\"=1.0.0\"", &format!("\"={target}\""))
+    );
